const initialData = {
  "operationsArray": [
    {
      "frequency": 100
    }
  ]
};
const customTheme = createTheme({
  palette: {
    mode: 'dark',
    background: {
      paper: tertiaryColor,
    },
  },
  shape: {
    borderRadius: 0,
  },
  spacing: 3,
});

const Container = { padding: "10px 10px", display: "flex", flexDirection: "column", backgroundColor: primaryColor };
const Header = { padding: "10px 20px", textAlign: "center", color: "white"};
const LabelContainer = { display: "flex", justifyContent: "center", alignItems: "center"};
const Label = { padding: "10px 20px", textAlign: "center", color: "white" };
const Form = { margin: "20px 200px" , padding: "10px 10px", backgroundColor: secondaryColor }
const Button = { color: "white", padding: "5px 15px", margin: "10px 0px", backgroundColor: "#27139c" };
const Output = {color: "white"};
var OutputLabel = "Not Ready";



function App() {
  const [data, setData] = useState(initialData);
  return (
    <div style={Container}>
      <h2 style={Header}>DOTS_Framework Builder Tool</h2>
      <div style={LabelContainer}>
        <label style={Label}>
          This form simplifies the process of building a DOTS mod without needing to know anything about JSON files or OpenMW Lua terminology.
        </label>
      </div>
      <div style={LabelContainer}>
        <label style={Label}>
          Fill out all required portions of the form, and then copy/paste the JSON output at the bottom of the page and save it in the DOTS Mods directory as a .json file.
        </label>
      </div>
      <div className='App' style={Form}>
        <ThemeProvider theme={customTheme}>
          <JsonForms
            schema={schema}
            uischema={uischema}
            data={data}
            renderers={renderers}
            cells={materialCells}
            onChange={({ data, errors }) => setData(data)}
          />
        </ThemeProvider>
      </div>
        <div style={Container}>
          <label style={Label}>
          {OutputLabel}
          </label>
          <button style = { Button } onClick={clickMe(data)}></button>
          <pre style = { Output } >{JSON.stringify(data, null, 2)}</pre>
        </div>
    </div>
  );
}


function clickMe(data) {
  let outputData = JSON.stringify(data)
  if (outputData.includes("modName"))
    OutputLabel ="You have supplied a modname!";
  else
    OutputLabel = "You have not supplied a modname!";
}

export default App;


